def time_diff_humanized(seconds: int) -> str:
    if seconds == 0:
        return "0s"

    units = []
    if seconds >= 86400:
        days = seconds // 86400
        units.append(f"{days}d")
        seconds %= 86400
    if seconds >= 3600:
        hours = seconds // 3600
        units.append(f"{hours}h")
        seconds %= 3600
    if seconds >= 60:
        minutes = seconds // 60
        units.append(f"{minutes}m")
        seconds %= 60
    if seconds > 0:
        units.append(f"{seconds}s")

    return " ".join(units)

