def evaluate_simple_expression(expr: str) -> int:
    expr = expr.replace(" ", "")
    stack = []
    operators = set(['+', '-', '*', '/'])
    i = 0
    while i < len(expr):
        if expr[i] in operators:
            stack.append(expr[i])
            i += 1
        else:
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            stack.append(num)
            if stack[-2] == '/':
                if num == 0:
                    raise ZeroDivisionError
                stack.pop()
                stack.pop()
                stack.append(int(stack[-1] / num))
            elif stack[-2] == '*':
                stack.pop()
                stack.pop()
                stack.append(stack[-1] * num)
    while len(stack) > 1:
        op = stack.pop()
        b = stack.pop()
        a = stack.pop()
        if op == '+':
            stack.append(a + b)
        elif op == '-':
            stack.append(a - b)
    return stack[0]
